-- Create "roles" table
CREATE TABLE "public"."roles" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "deleted_by" bigint NULL,
  "name" character varying NOT NULL,
  "level" bigint NOT NULL DEFAULT 0,
  "parent_id" bigint NOT NULL DEFAULT -1,
  "lft" bigint NOT NULL DEFAULT 0,
  "rgt" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
-- Create index "roles_name_key" to table: "roles"
CREATE UNIQUE INDEX "roles_name_key" ON "public"."roles" ("name");
-- Create "users" table
CREATE TABLE "public"."users" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "deleted_by" bigint NULL,
  "username" character varying NOT NULL,
  "role_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "users_roles_users" FOREIGN KEY ("role_id") REFERENCES "public"."roles" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "users_username_key" to table: "users"
CREATE UNIQUE INDEX "users_username_key" ON "public"."users" ("username");
-- Create "credentials" table
CREATE TABLE "public"."credentials" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "deleted_by" bigint NULL,
  "type" character varying NOT NULL,
  "credential_data" jsonb NOT NULL,
  "user_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "credentials_users_credentials" FOREIGN KEY ("user_id") REFERENCES "public"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create "federated_identities" table
CREATE TABLE "public"."federated_identities" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "deleted_by" bigint NULL,
  "provider" character varying NOT NULL,
  "external_id" character varying NOT NULL,
  "user_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "federated_identities_users_federated_identities" FOREIGN KEY ("user_id") REFERENCES "public"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "federatedidentity_provider_external_id" to table: "federated_identities"
CREATE UNIQUE INDEX "federatedidentity_provider_external_id" ON "public"."federated_identities" ("provider", "external_id");
-- Create index "federatedidentity_user_id_provider" to table: "federated_identities"
CREATE UNIQUE INDEX "federatedidentity_user_id_provider" ON "public"."federated_identities" ("user_id", "provider");
-- Create "resources" table
CREATE TABLE "public"."resources" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "deleted_by" bigint NULL,
  "key" character varying NOT NULL,
  "description" character varying NULL,
  PRIMARY KEY ("id")
);
-- Create index "resources_key_key" to table: "resources"
CREATE UNIQUE INDEX "resources_key_key" ON "public"."resources" ("key");
-- Create "permissions" table
CREATE TABLE "public"."permissions" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "deleted_by" bigint NULL,
  "description" character varying NULL,
  "scopes" bigint NOT NULL DEFAULT 0,
  "resource_id" bigint NOT NULL,
  "role_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "permissions_resources_permissions" FOREIGN KEY ("resource_id") REFERENCES "public"."resources" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "permissions_roles_permissions" FOREIGN KEY ("role_id") REFERENCES "public"."roles" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "permission_role_id_resource_id" to table: "permissions"
CREATE UNIQUE INDEX "permission_role_id_resource_id" ON "public"."permissions" ("role_id", "resource_id");
-- Create "problems" table
CREATE TABLE "public"."problems" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "deleted_by" bigint NULL,
  "title" character varying NOT NULL,
  "description" text NOT NULL,
  "difficulty" character varying NOT NULL,
  "time_limit_ms" bigint NOT NULL DEFAULT 1000,
  "memory_limit_kb" bigint NOT NULL DEFAULT 262144,
  "is_published" boolean NOT NULL DEFAULT false,
  "author_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "problems_users_problems" FOREIGN KEY ("author_id") REFERENCES "public"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create "tags" table
CREATE TABLE "public"."tags" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "deleted_by" bigint NULL,
  "name" character varying NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "tags_name_key" to table: "tags"
CREATE UNIQUE INDEX "tags_name_key" ON "public"."tags" ("name");
-- Create "problem_tags" table
CREATE TABLE "public"."problem_tags" (
  "problem_id" bigint NOT NULL,
  "tag_id" bigint NOT NULL,
  PRIMARY KEY ("problem_id", "tag_id"),
  CONSTRAINT "problem_tags_problem_id" FOREIGN KEY ("problem_id") REFERENCES "public"."problems" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "problem_tags_tag_id" FOREIGN KEY ("tag_id") REFERENCES "public"."tags" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create "test_cases" table
CREATE TABLE "public"."test_cases" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "deleted_by" bigint NULL,
  "input" text NOT NULL,
  "expected_output" text NOT NULL,
  "is_sample" boolean NOT NULL DEFAULT false,
  "order_index" bigint NOT NULL,
  "problem_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "test_cases_problems_test_cases" FOREIGN KEY ("problem_id") REFERENCES "public"."problems" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create "attribute_definitions" table
CREATE TABLE "public"."attribute_definitions" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "deleted_by" bigint NULL,
  "key" character varying NOT NULL,
  "data_type" character varying NOT NULL DEFAULT 'string',
  "description" character varying NULL,
  PRIMARY KEY ("id")
);
-- Create index "attribute_definitions_key_key" to table: "attribute_definitions"
CREATE UNIQUE INDEX "attribute_definitions_key_key" ON "public"."attribute_definitions" ("key");
-- Create "user_attribute_values" table
CREATE TABLE "public"."user_attribute_values" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "deleted_by" bigint NULL,
  "value" text NOT NULL,
  "attribute_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "user_attribute_values_attribute_definitions_values" FOREIGN KEY ("attribute_id") REFERENCES "public"."attribute_definitions" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "user_attribute_values_users_attributes" FOREIGN KEY ("user_id") REFERENCES "public"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "userattributevalue_user_id_attribute_id" to table: "user_attribute_values"
CREATE UNIQUE INDEX "userattributevalue_user_id_attribute_id" ON "public"."user_attribute_values" ("user_id", "attribute_id");
